<?php
declare(strict_types=1);
namespace Dreamsmith\Campaign\Reporting;
use DateTimeImmutable;use DateTimeZone;use PDO;
final class CampaignReportingService{
 public function __construct(private readonly PDO $pdo){}
 public function dashboard(array $campaign,string $timezone):array{$id=(int)$campaign['id'];$tz=new DateTimeZone($timezone);$today=(new DateTimeImmutable('now',$tz))->format('Y-m-d');$q=fn(string $sql,array $p=[])=>($s=$this->pdo->prepare($sql))&&$s->execute($p)?$s->fetchAll():[];$count=fn(string $sql,array $p=[])=>count($q($sql,$p))? (int)$q($sql,$p)[0]['value']:0;$funnel=$q("SELECT status,COUNT(*) total FROM prospects WHERE campaign_id=:id AND archived_at IS NULL GROUP BY status",['id'=>$id]);$pipeline=$q("SELECT stage,COUNT(*) total,CAST(COALESCE(SUM(value_amount),0) AS CHAR) value FROM opportunities o JOIN prospects p ON p.id=o.prospect_id WHERE p.campaign_id=:id AND p.archived_at IS NULL GROUP BY stage",['id'=>$id]);$queues=['overdue'=>$q("SELECT f.*,c.name company_name,CONCAT_WS(' ',ct.first_name,ct.last_name) contact_name FROM follow_ups f JOIN prospects p ON p.id=f.prospect_id LEFT JOIN companies c ON c.id=p.company_id LEFT JOIN contacts ct ON ct.id=p.primary_contact_id WHERE p.campaign_id=:id AND p.archived_at IS NULL AND f.status='open' AND DATE(f.due_at)<:today ORDER BY f.due_at LIMIT 10",['id'=>$id,'today'=>$today]),'today'=>$q("SELECT f.*,c.name company_name,CONCAT_WS(' ',ct.first_name,ct.last_name) contact_name FROM follow_ups f JOIN prospects p ON p.id=f.prospect_id LEFT JOIN companies c ON c.id=p.company_id LEFT JOIN contacts ct ON ct.id=p.primary_contact_id WHERE p.campaign_id=:id AND p.archived_at IS NULL AND f.status='open' AND DATE(f.due_at)=:today ORDER BY f.due_at LIMIT 10",['id'=>$id,'today'=>$today]),'ready'=>$q("SELECT p.*,c.name company_name,CONCAT_WS(' ',ct.first_name,ct.last_name) contact_name FROM prospects p LEFT JOIN companies c ON c.id=p.company_id LEFT JOIN contacts ct ON ct.id=p.primary_contact_id WHERE p.campaign_id=:id AND p.archived_at IS NULL AND p.status='ready_to_contact' ORDER BY p.updated_at LIMIT 10",['id'=>$id])];$targets=$q('SELECT metric_key,target_value FROM campaign_targets WHERE campaign_id=:id',['id'=>$id]);$actual=['selected_prospects'=>$count('SELECT COUNT(*) value FROM prospects WHERE campaign_id=:id AND archived_at IS NULL',['id'=>$id]),'personalized_contacts'=>$count("SELECT COUNT(DISTINCT i.prospect_id) value FROM interactions i JOIN prospects p ON p.id=i.prospect_id WHERE p.campaign_id=:id AND i.voided_at IS NULL AND i.direction='outbound' AND i.qualifies_as_contact=1",['id'=>$id]),'sales_conversations'=>$count("SELECT COUNT(DISTINCT prospect_id) value FROM prospect_status_events e JOIN prospects p ON p.id=e.prospect_id WHERE p.campaign_id=:id AND e.voided_at IS NULL AND e.to_status='conversation'",['id'=>$id]),'qualified_opportunities'=>$count("SELECT COUNT(*) value FROM opportunities o JOIN prospects p ON p.id=o.prospect_id WHERE p.campaign_id=:id",['id'=>$id]),'offers_sent'=>$count("SELECT COUNT(*) value FROM opportunities o JOIN prospects p ON p.id=o.prospect_id WHERE p.campaign_id=:id AND o.stage IN ('proposal_sent','won')",['id'=>$id]),'contracts_won'=>$count("SELECT COUNT(*) value FROM opportunities o JOIN prospects p ON p.id=o.prospect_id WHERE p.campaign_id=:id AND o.stage='won'",['id'=>$id])];foreach($targets as &$target)$target['actual']=$actual[$target['metric_key']]??0;unset($target);$contacts=$actual['personalized_contacts'];$conversations=$actual['sales_conversations'];return compact('funnel','pipeline','queues','targets','contacts','conversations','today');}
 public function recent(int $campaignId):array{$s=$this->pdo->prepare("SELECT * FROM (SELECT i.occurred_at at_time,'Interaction' kind,i.summary detail,i.prospect_id FROM interactions i JOIN prospects p ON p.id=i.prospect_id WHERE p.campaign_id=:id AND i.voided_at IS NULL UNION ALL SELECT e.occurred_at,'Prospect stage',e.to_status,e.prospect_id FROM prospect_status_events e JOIN prospects p ON p.id=e.prospect_id WHERE p.campaign_id=:id AND e.voided_at IS NULL UNION ALL SELECT e.occurred_at,'Opportunity stage',e.to_stage,o.prospect_id FROM opportunity_stage_events e JOIN opportunities o ON o.id=e.opportunity_id JOIN prospects p ON p.id=o.prospect_id WHERE p.campaign_id=:id AND e.voided_at IS NULL) activity ORDER BY at_time DESC LIMIT 15");$s->execute(['id'=>$campaignId]);return $s->fetchAll();}
}
